static int[] cyclicPlace(int[] nums) {
    int i = 0;
    while (i < nums.length) {
        int home = nums[i] - 1;
        if (nums[home] != nums[i]) {
            int t = nums[home];
            nums[home] = nums[i];
            nums[i] = t;
        } else {
            i++;
        }
    }
    return nums;
}

