static int[] applyInPlace(int[] items, int[] dest) {
    int n = items.length;
    for (int start = 0; start < n; start++) {
        if (dest[start] < 0) continue;
        int carry = items[start];
        int j = dest[start];
        dest[start] = ~dest[start];
        while (j != start) {
            int t = items[j];
            items[j] = carry;
            carry = t;
            int nxt = dest[j];
            dest[j] = ~dest[j];
            j = nxt;
        }
        items[start] = carry;
    }
    for (int i = 0; i < n; i++) dest[i] = ~dest[i];
    return items;
}

