        int carry = items[start];
        int j = dest[start];
        dest[start] = ~dest[start];
        while (j != start) {
            swap(items[j], carry);
            int nxt = dest[j];
            dest[j] = ~dest[j];
            j = nxt;
        }
        items[start] = carry;
    }
    for (int& d : dest) d = ~d;
    return items;
}

